package com._8x8.herd.device_logs.upload.storage.s3;

import com._8x8.herd.device_logs.upload.config.DeviceLogsProperties;
import com._8x8.herd.device_logs.upload.storage.LogStorage;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import software.amazon.awssdk.awscore.retry.AwsRetryStrategy;
import software.amazon.awssdk.regions.Region;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.S3ClientBuilder;

/**
 * The service's only S3 client, and the storage that uses it. Credentials come from the SDK's default chain, which
 * finds the Pod Identity role in AWS (ADR 0012), so no keys are in the config.
 */
@Configuration(proxyBeanMethods = false)
public class S3ClientConfig {

    @Bean
    S3Client s3Client(DeviceLogsProperties properties) {
        S3ClientBuilder builder = S3Client.builder()
                .region(Region.of(properties.aws().region()))
                .overrideConfiguration(c -> c
                        // The phone's body can be read only once, so a retry would have nothing left to send. A retry
                        // after a lost response would also collide with the first write. Phones don't retry on the
                        // 429 either, and nothing is lost: app.log carries its lines into the next upload, and the
                        // other files are full copies every time.
                        .retryStrategy(AwsRetryStrategy.doNotRetry())
                        .apiCallTimeout(properties.storage().writeTimeout()));
        if (properties.aws().endpointOverride() != null) {
            // A LocalStack host such as a compose service name doesn't resolve with the bucket as a subdomain.
            builder.endpointOverride(properties.aws().endpointOverride()).forcePathStyle(true);
        }
        return builder.build();
    }

    @Bean
    LogStorage logStorage(S3Client s3, DeviceLogsProperties properties) {
        return new S3LogStorage(s3, properties.storage().bucket());
    }
}
